 void Place(UIElement item,int column){Grid.SetColumn(item,column);layout.Children.Add(item);}
 static void Button(Panel panel,string text,Action action){var b=new Button{Content=text,Margin=new Thickness(2),Padding=new Thickness(6)};b.Click+=(_,_)=>{try{action();}catch(Exception ex){MessageBox.Show(L.T(ex.Message),"Facial Studio");}finally{if(Window.GetWindow(panel) is {} w)L.Apply(w);}};panel.Children.Add(b);}
