 void Refresh(){rows.ItemsSource=null;catalog.ItemsSource=mfee.Entries.Where(d=>((categoryFilter.SelectedItem as ComboBoxItem)?.Tag as string is not string category||category=="*"||d.Category==category)&&(d.Name+" "+d.Id+" "+d.Category).Contains(search.Text,StringComparison.OrdinalIgnoreCase)).Select(d=>new Choice(d.Id,d.Category+" / "+d.Name+(d.ApiRegistered?" [API]":" [?]"))).ToList();catalog.SelectedIndex=0;catalogStatus.Text=L.T("API 등록과 TRI 지원은 별개입니다.")+"\n"+mfee.Entries.Count(e=>e.ApiRegistered)+" / "+mfee.Entries.Count+" API";
