 internal void LoadPreviewSmoke(string setup,string preset){facePreview.Assets.LoadProfile(setup);Add(PresetFile.Load(preset));}
 internal void CleanForSmoke(){foreach(var document in documents)document.Dirty=false;clipPanel?.Pause();}
 internal void MorphEdited(){Changed();if(activeOnly.IsChecked==true)Refresh();}
 internal void DeleteMorph(Morph m){Current().Morphs.Remove(m);Changed();Refresh();}
 internal string MorphLabel(Morph m)=>(m.Backend=="MFG"?"MFG / ":mfee.Entries.Any(e=>e.ApiRegistered&&e.Name.Equals(m.Name,StringComparison.OrdinalIgnoreCase))?L.T("[API 등록] "):L.T("[API 미확인] "))+(facePreview.HasFace&&!facePreview.Supports(m)?L.T("[이 얼굴에서 미지원] "):"")+m.Name;
 void Open(){var d=new OpenFileDialog{Filter=L.T("표정 프리셋|*.facialpreset.json;*.json")};if(d.ShowDialog()==true){var p=PresetFile.Load(d.FileName);Add(p,d.FileName);}}
 void Save(bool other){if(clipPanel?.Active==true){MessageBox.Show(L.T("클립 패널의 클립 저장 버튼을 사용하세요."));return;}if(doc==null)return;string? path=other?null:doc.Path;if(path==null){var d=new SaveFileDialog{Filter=L.T("표정 프리셋|*.facialpreset.json"),FileName="preset.facialpreset.json"};if(d.ShowDialog()!=true)return;path=d.FileName;}PresetFile.Save(path,Editing!);doc.Path=path;doc.Dirty=false;presets.Items.Refresh();}
