 void Delete(){if(doc==null)return;if(MessageBox.Show(L.T("저장하지 않은 변경은 잃게 됩니다. 목록에서 제거할까요? 취소하려면 아니요를 누르세요. 저장 파일은 삭제하지 않습니다."),L.T("프리셋 제거"),MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;var old=doc;presets.Items.Remove(old);documents.Remove(old);if(documents.Count>0)presets.SelectedIndex=0;else Add(new Preset());}
